contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.Initialized(); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceBefore = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceAfter = address(c).balance;

        assert(balanceAfter == balanceBefore + depositAmount && contractBalanceAfter == contractBalanceBefore + depositAmount);
    }

    receive() external payable {}
}

