// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Initialized() {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint256 contractBalanceBefore = address(c).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint256 contractBalanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore + depositAmount && contractBalanceAfter == contractBalanceBefore + depositAmount);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
